bool in_str(xstring str_look,xstring full_str)
{
int f_str = full_str.find(str_look);
if(f_str == -1)
return false;
else
return true;
}

xstring loop_str(xstring full_str,int num)
{
int i = 0.;
xstring temp_str;
xstring cut_str;
cut_str = full_str;
if(full_str.find(",") == -1)
return full_str;
while(cut_str.find(",") != -1){
i = i + 1;
temp_str = cut_str.substr(0,cut_str.find(","));
cut_str = cut_str.substr(cut_str.find(",") + 1,cut_str.length());
if(i == num)
break;
}
if(i == num)
return temp_str;
else
return cut_str;
}

