}
return i + 1;
}

void validate_data(void) {
if (elapsed_months_w != 0 && eq(projection_type,"NEW_BUS"))
write_msg(0, "If New_Bus projection type, then elapsed months must be zero.");
if (prem_term_w > benefit_term_w)
write_msg(0, "prem_term > benefit_term.");
// *** removed to allow backward layering for re-create
//if (layer>0 && !eq(projection_type, "NEW_BUS"))
//
throw NonFatalError ("If layering is required projection_type must be new business.");
if (eq(projection_type,"NEW_BUS") && !eq(target_column,"appraisal_value"))
write_msg(0,"For a new business run, the target must be set to appraisal_value.");
if (pv_period != 12)
write_msg(0, "Template set up for monthly projections. Change the discount period in
task.");
if (eq(projection_type,"VALN") && elapsed_months_w < 0)
write_msg(0,"elapsed_months < 0." );
//if (eq(projection_type,"VALN") && elapsed_months_w == 0) {
//
projection_type = "PRICING";
//}
if (elapsed_months_w >= benefit_term_w)
write_msg(0, "elapsed_months >= benefit_term.");
// Ensure frequencies given are factors of 12.
if (policy_pup_status == "N" || prem_term_w > elapsed_months_w){
if (prem_freq_w == 0)
write_msg(0,"Premium frequency must be 1, 2, 3, 4, 6, or 12.");
// Premium frequency must be a multiple of 12 whilst premiums are being paid
if  (12 % prem_freq_w != 0)
write_msg(0, "Premium frequency must be 1, 2, 3, 4, 6, or 12.");
}
if (policy_pup_status == "N" && prem_curr_total <= 0.0)
write_msg(0, "policy_pup_status == 'N' && prem_curr_total <= 0.0.");
if (old_adif && policy_pup_status == "N" && saving_prop < allocation_rate(1))
write_msg(0,"old_adif && policy_pup_status == 'N' && saving_prop < allocation_rate_1.");
if((unit_value_accum_w + unit_value_savings) < SMALL_DOUBLE && prem_curr_total <= 0.0)
write_msg(0,"No Accumulation or Premium.");
// close function
}

int valn_day_calc( int month) {
std::vector<int> daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
int leapyear = 0.;
if((valn_year % 4 == 0 && valn_year % 100 !=0 ) || (valn_year % 400 == 0))
leapyear = 1.;
//  מעוברת שנה זו אם-  מקבל פברואר29 ימים
if (month == 2 && leapyear == 1) {
return 29;
}
return daysInMonth[month - 1]; //  מבוסס המערך0  מפחיתים ולכן1
}

int valn_month_calc(int date) {
if((date / 100) % 100 == 1 )
return 12.;
return (date / 100) % 100 - 1 ;
}

int valn_year_calc(int date) {
if ( (date / 100) % 100 == 1 )
return int(date / 10000) - 1 ;
return int(date / 10000) ;
}

void write_msg(int type, xstring msg) {
//Make the policy number and group fields 10 and 20 characters respectively.
xstring mypolnum = pol_number;
mypolnum.resize(10);
xstring mygroup = group;
mygroup.resize(20);
xstring prefix = pol_number + " - " + mygroup + " - ";
if (type == 0) {
xstring message = prefix + msg;
throw NonFatalError(message);
}
if (type == 1) {
xstring message = "Policy valued: " + prefix + msg;
log_strm << message << endl;
}
return ;
} //close function

