double compute_disc_rate(int i) {
xstring int_set_name = main->int_set;
if(main ->sensitivities == "Y")
{
xstring var_name = main-> sensitivities_tbl(1, "table");
if(var_name == "rate_vectors_tbl")
{
int_set_name = "SENS_INT";
}
}
if (main->run_type == "INT_DW" || main->run_type == "INT_UP") {
int_set_name = main->int_set + "_" + main->run_type;
}
if (main->interpolation != 0) {
if (i == 0 || i == 1) {
return pow(1. + main->rate_vectors_tbl(i, main->previous_int_set), main->interpolation
/ 12.0) *
pow(1. + main->rate_vectors_tbl(i, main->int_set), (12.0 - main->interpolation)
/ 12.0) - 1 +
liq_prem_pct * liq_prem_value;
}
else {
return pow(1. + main->rate_vectors_tbl(i - 1, int_set_name), main->interpolation /
12.0) *
pow(1. + main->rate_vectors_tbl(i, int_set_name), (12.0 - main->interpolation) /
12.0) - 1 +
liq_prem_pct * liq_prem_value;
}
}
return main->rate_vectors_tbl(i, int_set_name) + liq_prem_pct * liq_prem_value;
}

