rate = min(1.0, rate);
rate_1 = max(0.0, rate_1);
if ( t == 1 && elapsed_months != 0.0)
return (1. - pow((1. - rate), 1./12.)) + rate_1;
return 1. - pow((1. - rate), 1./12.);

