* basic_prop_units_b(t) * adif->surr_chg_perc_units;
* basic_prop_units_b(t) * adif->surr_chg_perc_units[xint(adif-
>pol_year(t))];
// If there is no PUP SV rebate, then paid-up units have already been reduced by the charge when
