int i = 0.;
xstring cut_str;
cut_str = full_str;
if(full_str.find(",") == -1)
return 1.;
while(cut_str.find(",") != -1){
i = i + 1;
cut_str = cut_str.substr(cut_str.find(",") + 1,cut_str.length());
}
return i + 1;
}

