void set_work_variables(){
//int i,j,k,xx,xxx,max_mat_age;
int i,j,k,xx,xxx;
int lookup_index;
// add modal loading to premium and policy fee (discounts and u/w loading will then be applied to
this too)
prem_curr_w = (prem_curr_w * (1.+ underwriting_load_med_w + underwriting_load_occ_w) +
mort_add_permil_w * (sum_insured_curr_w))*(1. + modal_loading_w);
policy_fee_curr_w = policy_fee_curr_w * (1. + modal_loading_w);
reserve_init = res_init_nonpar + res_init_par;
// ****** Calculate commencement and maturity periods *************************
// commence_period_w is that value of t at which the policy starts.
// For example, if the policy commenced 12 months prior to the valuation
// date then commence_period_w = -12.
// A policy starting 6 months after the valuation date (future new business)
// will have commence_period_w = 6, since it's elapsed months is negative.
commence_period_w = -elapsed_months;
// Sometimes reference needs to be made to the valuation date for an in-force
// policy or to the policy commencement for a future new business policy. This
// is achieved by using commence_nonneg_w.
if (xint(prod_year)<valn_year)
commence_nonneg_w = max(0, commence_period_w);
else
commence_nonneg_w = max(-11, commence_period_w);
// Limit Benefit Term according to maximum maturity age
//DH 6/5/18: Code before adding maximum maturity age
max_mat_age = main->product_param_tbl_lat(ben_class_w,"max_maturity_age");
if (xint(age_exact_issue + elapsed_months/12) < max_mat_age) {
benefit_term_w = min(benefit_term_w,(max_mat_age - age_exact_issue)*12);
prem_term_w = min(prem_term_w,benefit_term_w);
}
// maturity_period_w is that value of t at which the policy ends.
// A LTC policy can have a claim period that continues past the policy (coverage) period, in which
