int str_parts(xstring full_str)
{
int i = 0.;
xstring cut_str;
cut_str = full_str;
if(full_str.find(",") == -1)
return 1.;
while(cut_str.find(",") != -1){
i = i + 1;
cut_str = cut_str.substr(cut_str.find(",") + 1,cut_str.length());
}
return i + 1;
}

void validate_data(void) {
if (prem_curr_w <= 0.0 &&  policy_pup_status == "N" && prem_type == "FIXED")
write_msg(SKIP, "Premium must be greater than zero for a premium-paying policy.");
if (pv_period != 12)
write_msg(SKIP,"Application is set up for monthly projections. Change the discount period in
the projection task.");
// Ensure frequencies given are factors of 12.
if ((12 % prem_freq_w != 0.0) ||
(prem_freq_w == 0) || (prem_freq_w == 0 && prem_term_w > elapsed_months))  // premium
frequency must be a multiple of 12 and must
// not be zero whilst premiums are being paid.
write_msg(SKIP, "Premium frequency must be 1, 2, 3, 4, 6, or 12.");
if (prem_term_w < 2 &&  policy_pup_status == "N")
write_msg(SKIP, "Prem_term too low for premium paying policy ");
if ((sum_insured_curr_w) < SMALL_DOUBLE)
write_msg(SKIP, "Benefit amount is zero or negative.");
if (benefit_term_w <= elapsed_months)
write_msg(SKIP,  "benefit_term <= elapsed_months.");
// close function
}

int valn_day_calc( int month) {
std::vector<int> daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
int leapyear = 0.;
if((valn_year % 4 == 0 && valn_year % 100 !=0 ) || (valn_year % 400 == 0))
leapyear = 1.;
//  מעוברת שנה זו אם-  מקבל פברואר29 ימים
if (month == 2 && leapyear == 1) {
return 29;
}
return daysInMonth[month - 1]; //  מבוסס המערך0  מפחיתים ולכן1
}

int valn_month_calc(int date) {
if((date / 100) % 100 == 1 )
return 12.;
return (date / 100) % 100 - 1 ;
}

int valn_year_calc(int date) {
if ( (date / 100) % 100 == 1 )
return int(date / 10000) - 1 ;
return int(date / 10000) ;
}

void write_msg(int type, xstring msg) {
//Make the policy number and group fields 10 and 20 characters respectively.
xstring mypolnum = pol_number;
mypolnum.resize(10);
xstring mygroup = group;
mygroup.resize(20);
xstring prefix = pol_number + " - " + mygroup + " - ";
if (type == SKIP) {
xstring message = prefix + msg;
throw NonFatalError(message);
}
if (type == LOG) {
xstring message = "Policy valued: " + prefix + msg;
log_strm << message << endl;
}
return ;
} //close function

